# I generate the complete LaTeX report from the numerical R outputs.
entry <- sub("^--file=", "", commandArgs(FALSE)[grepl("^--file=", commandArgs(FALSE))][1])
source(file.path(dirname(normalizePath(entry)), "common.R"))
S <- read_json(file.path(OUT, "summary.json"))
A <- S$audit; D <- S$primary; B <- S$paired_bootstrap; L <- S$leakage_paired; T <- S$transitions
V <- setNames(S$specifications, vapply(S$specifications, function(x) x$specification, character(1)))
n <- function(x) formatC(as.integer(x), format = "d", big.mark = ",")
f <- function(x, d = 1L) formatC(as.numeric(x), format = "f", digits = d, big.mark = ",")
pct <- function(x) paste0(f(as.numeric(x) * 100, 1), "\\%")
esc <- function(s) {
  for (character in c("&", "_", "%", "#")) s <- gsub(character, paste0("\\", character), as.character(s), fixed = TRUE)
  s
}
add <- function(x) parts <<- c(parts, paste0(x, intToUtf8(10)))
section <- function(x) add(paste0("\\section{", x, "}"))
sub <- function(x) add(paste0("\\subsection{", x, "}"))
fig <- function(name, caption, height = NULL) {
  opts <- if (is.null(height)) "width=\\textwidth" else paste0("width=\\textwidth,height=", height, ",keepaspectratio")
  add(paste0("\\begin{figure}[H]\\centering\\includegraphics[", opts, "]{figures/", name,
    ".pdf}\\caption{", caption, "}\\end{figure}"))
}
table <- function(headers, rows, layout, caption) {
  bs <- intToUtf8(92); row_end <- paste0(bs, bs)
  add(paste0(bs, "begin{table}[H]", bs, "centering", bs, "small", bs, "caption{", caption,
    "}", bs, "begin{tabular}{", layout, "}", bs, "toprule"))
  add(paste0(paste(unlist(headers), collapse = " & "), " ", row_end, " ", bs, "midrule"))
  for (row in rows) add(paste0(paste(unlist(row), collapse = " & "), " ", row_end))
  add(paste0(bs, "bottomrule", bs, "end{tabular}", bs, "end{table}"))
}

parts <- unlist(list("\\documentclass[11pt,a4paper]{article}\n\\usepackage[margin=24mm,headheight=15pt]{geometry}\n\\usepackage[T1]{fontenc}\n\\usepackage{mathpazo,helvet,courier}\n\\usepackage{graphicx,booktabs,longtable,array,amsmath,amssymb,xcolor,float,fancyhdr,titlesec,hyperref}\n\\definecolor{ink}{HTML}{243746}\n\\definecolor{accent}{HTML}{256B91}\n\\definecolor{rust}{HTML}{B35828}\n\\hypersetup{colorlinks=true,linkcolor=accent,urlcolor=accent,citecolor=accent,pdftitle={Rating shifts without identified skill shifts},pdfauthor={nakshatra0904}}\n\\titleformat{\\section}{\\Large\\sffamily\\bfseries\\color{ink}}{\\thesection}{.6em}{}\n\\titleformat{\\subsection}{\\large\\sffamily\\bfseries\\color{ink}}{\\thesubsection}{.6em}{}\n\\pagestyle{fancy}\\fancyhf{}\\fancyhead[L]{\\small\\sffamily Chess rating policy and measurement}\\fancyhead[R]{\\small\\sffamily Empirical report}\\fancyfoot[C]{\\thepage}\n\\setlength{\\parindent}{0pt}\\setlength{\\parskip}{6pt}\n\\renewcommand{\\arraystretch}{1.15}\n\\setlength{\\emergencystretch}{3em}\n\\newcommand{\\note}[1]{{\\small\\color{ink} #1}}\n\\begin{document}\n\\hypersetup{pageanchor=false}\n\\begin{titlepage}\n\\vspace*{1.1cm}\n{\\sffamily\\color{accent}\\large ONLINE CHESS / APPLIED ECONOMETRICS\\par}\n\\vspace{1cm}\n{\\sffamily\\bfseries\\color{ink}\\fontsize{30}{36}\\selectfont Rating shifts without identified skill shifts\\par}\n\\vspace{.7cm}\n{\\sffamily\\Large A difference-in-differences study of control-group sensitivity, participation, and post-game measurement around Chess.com's September 2020 reform\\par}\n\\vspace{1cm}\n{\\large Research and analysis by nakshatra0904\\par}\n{\\large R edition revised 12 October 2026\\par}\n\\vfill\n\\rule{\\textwidth}{.7pt}\n\\vspace{.3cm}\n\\textbf{Main research question}\\par\nHow much does an apparent rating-policy effect depend on the comparison pool, the players included, and the timing of the rating measurement?\\par\n\\vspace{.3cm}\n\\textbf{Data window}\\par\n1 June--31 October 2020. Public monthly Chess.com game archives, retrieved for a deterministically selected cohort.\\par\n\\vspace{.3cm}\n\\textbf{Evidence standard}\\par\nI estimate a difference-in-differences model, examine an event study and placebo breaks, and audit rating measurement. I distinguish empirical findings from the assumptions required for causal interpretation.\\par\n\\end{titlepage}\n\\pagenumbering{roman}\\hypersetup{pageanchor=true}\n\\begingroup\\small\\setlength{\\parskip}{0pt}\\tableofcontents\\endgroup\\clearpage\\pagenumbering{arabic}\n"))
section("Executive findings")
add(paste0("I analyze ", n(A[["unique_games"]]), " unique rated standard-chess games and ", n(A[["focal_observations"]]), " focal player-game observations from ", n(A[["july_active_n"]]), " July-active accounts, selected by screening ", n(A[["screened_n"]]), " accounts from a ", n(A[["frame_n"]]), "-account grandmaster sampling frame. I investigate an administrative rating change and distinguish displayed rating increases from improvement in chess skill."))
add(paste0("My primary two-way fixed-effects difference-in-differences (DiD) regression estimates a bullet-versus-blitz shift of \\textbf{", f(D[["estimate"]]), " rating points}, with an exploratory player-clustered 95\\% interval of [", f(D[["ci_low"]]), ", ", f(D[["ci_high"]]), "]. The estimation sample has ", n(D[["n_players"]]), " players and ", n(D[["n_cells"]]), " observed player-pool-week cells. This conditional contrast is a cohort-specific estimate; the policy was one platform-wide event, so its uncertainty is not fully captured by treating players as independent policy replications."))
add(paste0("A simpler matched-player calculation gives ", f(B[["estimate"]]), " points, with a player-resampling percentile interval of [", f(B[["ci_low"]]), ", ", f(B[["ci_high"]]), "]. The difference from the fixed-effects estimate reflects aggregation and weighting. Both estimates should be compared with the announced 150-point administrative offset, not interpreted as a gain of the same amount in latent ability."))
add(paste0("The joint test of the five nearest pre-event contrasts has p = ", f(S[["pretrend_p"]], 3), ". This diagnostic does not establish parallel trends: pre-tests may have limited power, and multiple co-occurring reforms threaten the comparison even when a pre-test does not reject. I therefore estimate several control definitions, common-player comparisons, pre-period placebos, and a differential-trend sensitivity model."))
add(paste0("The endpoint's ratings are recorded after the game. In ", n(S[["leakage_metrics"]][[1]][["n"]]), " observed adjacent decisive rematches, I compare retrospective performance metrics using post-game and prior-rematch ratings. The equal-pair mean improvement in log loss is ", f(L[["equal_pair_logloss_gain"]], 4), ", with a pair-resampling interval of [", f(L[["ci_low"]], 4), ", ", f(L[["ci_high"]], 4), "]. This is a measurement audit of information timing, not a new discovery that leakage can occur and not a deployable forecasting validation."))
add(paste0("\\textbf{The most useful distinction in this cohort.} ", paste0("Removing the directly reclassified 10|0 observations changes the main estimate by only ", f(abs((V[["Exclude 10|0; balanced; >=3 games"]][["estimate"]] - D[["estimate"]])), 2), " points. On the common ", n(V[["Common players: all blitz"]][["n_players"]]), "-account sample, changing the comparator from all blitz to 3|0 changes it by about ", f(abs((V[["Common players: all blitz"]][["estimate"]] - V[["Common players: 3|0 only"]][["estimate"]]))), " points. In contrast, weighting cells by their number of games raises the estimate from ", f(D[["estimate"]]), " to ", f(V[["All blitz; game-count weighted"]][["estimate"]]), " points. Thus weighting and participant support are more consequential than the direct 10|0 exclusion in this GM-oriented cohort; the result does not establish that comparator contamination is unimportant for the whole platform.")))
add("\\textbf{Contribution.} Prior work already analyzes rating prediction and post-game leakage. My narrower contribution is a reproducible sensitivity study connecting an actual reform to comparator contamination, changing participation, and measurement timing. In a targeted search, I found no directly matching study of this exact combined design; that is a limited search finding, not proof of worldwide novelty.")
section("Earlier work and the refined research question")
sub("What has already been done?")
add("Rating models and their uncertainty are established subjects. Glickman's original Glicko formulation adds rating uncertainty to skill estimation \\cite{glicko}. Current platform documentation distinguishes implementation details and player pools \\cite{chessratings,lichessratings}. I use established rating theory and interpret Chess.com points within their own platform and rating pool.")
add("Public applied projects also cover several obvious questions. Sharma's 2023 Chess.com analysis regresses rapid ratings on other ratings \\cite{sharma}. The ChessIQ repository explicitly identifies outcome leakage from post-game ratings and PGN fields \\cite{chessiq}. Smerdon's Fighting Chess Index demonstrates descriptive construction and regression adjustment of chess performance characteristics \\cite{smerdon}. These are direct examples of earlier work; the latter two are public project or author publications, not evidence that every nearby question has been peer reviewed.")
table(list("Earlier work", "Relevant overlap", "Distinction in this report"), list(list("Glickman, Glicko", "Uncertainty-aware ratings", "Empirical policy measurement"), list("Sharma (2023)", "Cross-pool regression", "Historical within-player contrasts"), list("ChessIQ project", "Post-game rating leakage", "Observed rematch audit near reform"), list("Smerdon (2021)", "Draw statistics and adjustment", "Policy comparator sensitivity"), list("DiD methods literature", "Trends and dependent errors", "Applied audit of one platform event")), "p{3cm}p{4.1cm}p{6cm}", "Related work and the narrower empirical contribution")
sub("Search scope and what novelty can mean")
add("I searched the public web and consulted primary pages on 11 October 2026. Query families included Chess.com / September 2020 / rating / regression; bullet / 150 / difference-in-differences; chess / post-game rating / leakage; chess / rating inflation / empirical study; and Chess.com / September 10 / control group. I found direct prior work on two candidate topics and narrowed my initial generic rating-prediction question. The repository contains the query ledger and verified source links.")
add("My search was targeted, not a systematic review of subscription databases, non-English theses, or every GitHub repository. I found no directly matched study in the results I reviewed. The appropriate novelty claim is therefore an original analysis of this frozen dataset and specification set, conditional on a documented search, rather than a claim that nobody has considered comparison-group sensitivity in chess.")
sub("Main question and secondary questions")
add("The central question is whether the apparent effect of a common rating rebase remains similar when the comparison pool and participant mix change. The simultaneous reclassification of 10-minute chess makes blitz a potentially affected comparator. Restricting observations to unchanged time controls may reduce direct composition changes, while leaving pool-wide spillovers unresolved.")
add("Three secondary questions are answered: (i) how much do game-weighted and equal-player comparisons differ; (ii) are first observed policy-crossing bullet changes compatible with an offset plus ordinary game updates; and (iii) how do result-associated rating updates alter performance metrics when measured ratings are used retrospectively? I defined all specifications before inspecting their estimated policy coefficients. I expanded the cohort from 128 to 256 screened accounts after observing activity counts, to improve coverage, without using estimated effects as a stopping rule.")
section("Policy context and what a rating measures")
add("Chess.com's 10 September 2020 announcement describes two changes: 10|0 games moved from blitz to rapid, and active bullet ratings received an administrative increase of 150 points. The bullet adjustment was applied on a subsequent live-chess login, with a short rollout delay. Eligible rapid ratings could also be raised to the player's higher blitz rating \\cite{policy}. The announcement date is therefore an intention-to-treat time marker, not an observed account-level treatment timestamp.")
add("A rating is an estimated coordinate within a population and implementation. A uniform offset $c$ applied to both players leaves their difference unchanged: $(r_i+c)-(r_j+c)=r_i-r_j$. Any expectation formula depending only on the difference is invariant to this common rebase. An increase in displayed points can thus be mechanically large while implying no change in relative expected score.")
add("For illustration, the Elo-shaped curve is $E_i=1/(1+10^{-(r_i-r_j)/400})$. A hypothetical update $r_i'=r_i+K(s_i-E_i)$ would depend on both result and expectation. This is an illustrative formula, not a reconstruction of Chess.com's Glicko updates. Historical rating deviation, update parameters, refunds, and exact login time are absent from the archives used here.")
fig("12_rebase_invariance", "Illustrative mechanism, not empirical observations: a uniform 150-point offset changes absolute levels but preserves pairwise differences. The curve is Elo-shaped and is not fitted to the cohort.")
add("Two timing details matter. First, the documented monthly-game JSON ratings are post-game measurements. Second, the PGN rating headers in these data match those JSON values. Treating them as pre-game inputs would import information generated by the outcome into an apparent prediction exercise \\cite{pubapi}. I use them as measured outcomes in the policy analysis and interpret the logistic regression as retrospective association.")
section("Data collection, provenance and sample construction")
sub("Reproducible sampling")
add(paste0("The public GM-title endpoint contained ", n(A[["frame_n"]]), " account names at retrieval. I ranked each normalized name by the SHA-256 digest of the fixed string \\texttt{chess-policy-2020-v1|} followed by that name. The first ", n(A[["screened_n"]]), " names formed the screening sample. Accounts with at least one rated standard bullet, blitz, or rapid game in July 2020 formed the historical active cohort (", n(A[["july_active_n"]]), " accounts). I retrieved complete available archives for June, July, August, September, and October 2020 for those accounts."))
add("This is deterministic pseudo-random selection from a contemporary title list, followed by historical activity screening. It is not a probability sample of all 2020 Chess.com users. Accounts that no longer appear in the current frame can be missing; players may have earned titles later; and inactive July accounts are deliberately excluded. Public handles identify accounts, not necessarily distinct people. I do not assume that these accounts already held GM titles in 2020.")
sub("Cleaning and observational units")
add("I retain rated standard chess in the three live speed classes, interpret White's result as 1, 0.5, or 0, require numeric ratings between 100 and 4000, normalize usernames, and deduplicate by game UUID (falling back to URL). I exclude variant chess, daily chess, unrated games, and unknown final results. I convert game finish timestamps to UTC; the window ends before 1 November 2020.")
add("I maintain two distinct observational units. The unique-game file contains each game once, even when both players are sampled. The focal player-game file contains one row for each sampled participant. A game with two cohort accounts contributes two focal rows but only one unique-game row. Descriptive participant ratings use the latter focal unit; win/draw summaries and outcome regressions use unique games. This prevents duplicate games from being treated as independent outcome observations.")
table(list("Stage / property", "Count"), list(list("Current GM account frame", n(A[["frame_n"]])), list("Accounts screened", n(A[["screened_n"]])), list("July-active cohort accounts", n(A[["july_active_n"]])), list("Retrieved archive game records", n(A[["archive_records"]])), list("Rejected archive rows", n(A[["rejected_archive_rows"]])), list("Repeated eligible archive appearances removed", n(A[["deduplicated_eligible_rows"]])), list("Unique eligible games", n(A[["unique_games"]])), list("Focal player-game observations", n(A[["focal_observations"]])), list("Primary panel players", n(D[["n_players"]])), list("Primary panel cells", n(D[["n_cells"]]))), "lr", "Sample construction and audit counts")
add(paste0("The observed eligible timestamps run from ", esc(A[["start"]]), " to ", esc(A[["end"]]), ". PGN and JSON rating values match in ", f(A[["pgn_rating_match_pct"]], 2), "\\% of unique games. Request URLs, retrieval times, status codes, content hashes, the frozen sampling frame, and the selected cohort are included. I record unavailable archives as missing and do not impute their games."))
sub("Descriptive statistics")
rows <- list()
for (x in S[["descriptive"]]) rows[[length(rows) + 1L]] <- list(x[["time_class"]], n(x[["observations"]]), n(x[["players"]]), f(x[["mean_rating"]]), f(x[["median_rating"]]), f(x[["sd_rating"]]), f(x[["p10_rating"]]), f(x[["p90_rating"]]))
table(list("Pool", "Obs.", "Accounts", "Mean", "Median", "SD", "P10", "P90"), rows, "lrrrrrrr", "Published post-game ratings among focal observations, June--October 2020")
add("These are game-weighted statistics: a frequent player contributes more observations. The distribution describes this selected cohort's activity, not platform-wide percentiles. Standard deviation describes observed dispersion and is not a standard error. Game outcomes, repeated opponents, and account activity induce dependence that is addressed in model uncertainty only to the extent described below.")
fig("02_distributions", "Focal post-game rating distributions before and on/after 10 September 2020. Frequency polygons use 100-point bins and are normalized within pool-period. Source: frozen Chess.com cohort archives, June--October 2020.")
section("Difference-in-differences design and assumptions")
sub("Two-way fixed-effects DiD specification")
add("I anchor seven-day event bins at 00:00 UTC on 10 September 2020. Week $k=\\lfloor(t-t_0)/7\\text{ days}\\rfloor$ is based on game completion time. I omit week 0 (10--16 September) from panel estimation because treatment timing is imprecise. My main panel retains player-pool-week cells containing at least three focal games. Each retained account must have observed qualifying bullet and blitz cells in both periods; it need not appear in every week.")
add("I use difference-in-differences: bullet is the treated pool and blitz is the comparison pool for the same accounts. I compare their changes before and after the announcement, excluding the rollout week. My two-way fixed-effects least-squares specification is\n\\begin{equation}\n\\bar R_{ict}=\\alpha_{ic}+\\lambda_t+\\beta\\,\\mathbf{1}(c=\\mathrm{bullet})\\mathbf{1}(t\\geq1)+\\varepsilon_{ict}.\n\\end{equation}\nHere $\\alpha_{ic}$ is a player-by-pool fixed effect, $\\lambda_t$ is an event-week fixed effect, and $\\bar R$ is the mean published post-game rating in the cell. Observed cells receive equal weight. I also estimate a sensitivity model weighted by game count; neither weighting guarantees representativeness.")
add("The coefficient compares the change in bullet with the contemporaneous change in blitz after accounting for persistent player-pool levels and common weekly shifts. Its causal interpretation would require parallel untreated trends in bullet versus the chosen control, no relevant spillovers into blitz, no differential measurement changes, and ignorable changes in observation. These requirements are not secured by the public data.")
sub("Uncertainty and diagnostic tests")
add("I calculate regression intervals with the R cluster-robust sandwich covariance, clustering by account and using a Student-$t$ reference with the cluster degrees-of-freedom correction \\cite{rstats,zeileis}. I additionally bootstrap entire player contrasts 10,000 times using seed 20201011 and R's Mersenne-Twister generator. The resampling intervals are recomputed in R; identical integer seeds need not produce identical draws across software implementations. This retains within-player dependence, but is a different aggregate estimand from the fixed-effects coefficient. Bootstrap intervals use percentiles, not a claim of exact small-sample coverage.")
add("Many games do not imply many independent policy changes. Players share opponents, pool dynamics, and a single announcement. Account clustering does not capture every cross-player shock. The econometric literature documents sensitivity to serial correlation and to having few policy changes \\cite{bertrand,conley}. Reported intervals are useful cohort-level diagnostics and do not establish the uncertainty of a counterfactual platform-wide reform effect.")
add("I estimate an event study interacting bullet status with each observed event week, relative to week -1. I jointly test the five contrasts for weeks -6 through -2 as a near-event pre-trend diagnostic. I use four earlier dates as placebo breaks, restricting their estimation to pre-announcement observations. Non-rejection is not proof of the identifying assumption, and post-selection on a pre-test can distort inference \\cite{roth}. All these checks are exploratory, with no multiplicity-adjusted family-wise significance claim.")
sub("Why a sharp regression discontinuity is not used")
add("There is no observed assignment score with a treatment threshold. Calendar time is shared by everyone and coincides with other platform changes, so a sharp regression discontinuity in time would require strong assumptions about contemporaneous shocks. I also do not infer treatment receipt from an outcome-derived rating jump: doing so would select treatment on the dependent variable. The date-indexed design is an announcement-based panel contrast.")
fig("13_causal_structure", "Conceptual causal structure. Participation and opponent mix can affect measured ratings; game results also enter post-game ratings. The diagram summarizes mechanisms and is not an estimated causal graph.")
section("Descriptive behavior around the announcement")
fig("01_activity", "Focal game observations and their pool shares in anchored seven-day event bins. Boundary bins are incomplete calendar exposure; every series describes the sampled archives, not total site activity. Source: Chess.com archives, June--October 2020.")
add("The activity plot identifies changes in the observed mix before interpreting mean ratings. A higher mean can arise because stronger or more active accounts play more games, because players move between speed classes, or because the same players receive a rebase. Weekly game counts are descriptive; no exposure-adjusted behavioral treatment effect is estimated from these counts.")
fig("03_rating_trends", "Equal-account weekly means: each account with observed games in a pool-week contributes its own mean rating once. The set of accounts can change by week. Source: Chess.com cohort archives, June--October 2020.")
add("Equal-player weighting reduces domination by high-volume players but does not hold membership fixed. The fixed-effects panel and paired-player contrasts below address a different question: how observed ratings changed within accounts that appear in both periods and both main pools. A visual discontinuity in an unbalanced mean is therefore supporting description, not the identifying evidence.")
section("DiD estimates, event study and sensitivity")
add(paste0("My primary DiD estimate is ", f(D[["estimate"]]), " points (clustered SE ", f(D[["se"]]), "; ", n(D[["n_players"]]), " account clusters). The estimate differs from the announced offset by ", f((D[["estimate"]] - 150)), " points. This discrepancy can reflect later ordinary rating updates, incomplete treatment exposure, the behavior of the comparison pool, and the sample weighting. It does not by itself demonstrate that Chess.com implemented the policy incorrectly."))
rows <- list()
for (x in S[["specifications"]]) rows[[length(rows) + 1L]] <- list(esc(x[["specification"]]), f(x[["estimate"]]), paste0(paste0(f(x[["ci_low"]]), " to "), f(x[["ci_high"]])), n(x[["n_players"]]), n(x[["n_cells"]]))
table(list("Specification", "Estimate", "95\\% interval", "Players", "Cells"), rows, "p{6.2cm}rrrr", "Difference-in-differences estimates, in rating points; account-clustered intervals")
fig("04_did_sensitivity", "Each marker is a separate player-pool-week fixed-effects estimate with an exploratory 95\\% account-clustered interval. Some specifications change the eligible accounts as well as the controls. Source: Chess.com cohort archives, June--October 2020.")
add("The unchanged-control comparison restricts blitz to 3|0, while another specification excludes 10|0 only. My planned 5|0 comparison did not retain the minimum three eligible account clusters, so I omit that specification. These are controls defined by recorded game settings, not randomized comparison groups. The common-player pair of specifications holds the account set fixed between all-blitz and 3|0 comparisons, helping separate account selection from the choice of control observations. Weekly activity support may still differ.")
add("The unbalanced model admits more player-pool trajectories; the one-game threshold retains noisier cells; the shorter window reduces long-run drift; the game-count weighting changes the target toward frequent play; and the differential linear-trend model allows bullet to drift differently before and after the break. These are substantive sensitivity checks, not independent confirmations. A trend model also imposes a functional form and can extrapolate a noisy pre-trend.")
fig("05_event_study", "Event-study bullet-versus-blitz contrasts relative to week -1. Week 0 is excluded. Bars are exploratory account-clustered 95\\% intervals; the dotted 150-point line is a policy benchmark. Source: the primary cohort panel, June--October 2020.")
add(paste0("For the near-event pre-period joint test, p = ", f(S[["pretrend_p"]], 3), ". The full event-study path, including uncertainty, is more informative than treating that single number as a pass/fail gate. Persistent lead differences, wide intervals, or large placebo estimates weaken the case that an observed post-event change is attributable entirely to the announcement."))
rows <- lapply(S[["placebos"]], function(x) list(as.character(x[["cutoff"]]), f(x[["estimate"]]), paste0(paste0(f(x[["ci_low"]]), " to "), f(x[["ci_high"]])), f(x[["pvalue"]], 3)))
table(list("Placebo event week", "Estimate", "95\\% interval", "p-value"), rows, "rrrr", "Pre-announcement placebo breaks, using the primary accounts and pre-period cells only")
fig("06_player_changes", "Each point is a matched account: equal-week post-minus-pre bullet and blitz changes. The right panel shows their differences; the 150-point line is an announced-offset benchmark. Source: the primary panel.")
add(paste0("The matched-player bootstrap estimate is ", f(B[["estimate"]]), " points, with interval [", f(B[["ci_low"]]), ", ", f(B[["ci_high"]]), "]. The player distribution makes heterogeneity visible. Accounts with large changes should not be labeled as unusually improved or as suspicious: the measure includes estimation noise, elapsed time, ordinary results, and selection into play."))
section("Participation, reclassification and the comparator problem")
fig("07_composition", "Two different descriptive estimands: all-game mean changes versus mean within-account changes among accounts observed in both periods. Their difference combines activity weighting and account composition. Source: Chess.com archives, June--October 2020.")
rows <- lapply(S[["composition"]], function(x) list(x[["pool"]], f(x[["pooled_game_weighted_change"]]), f(x[["balanced_equal_player_change"]]), n(x[["balanced_players"]]), n(x[["pre_players"]]), n(x[["post_players"]])))
table(list("Pool", "All-game change", "Matched change", "Matched", "Pre", "Post"), rows, "lrrrrr", "Participation and weighting contrasts; ratings in points, account counts at right")
add("This is an estimand comparison rather than an exact causal decomposition. The two changes use different weights and different sets of accounts. It demonstrates how a pooled statistic can tell a different story from equal-player within-account changes, without assigning the entire difference to one mechanism.")
add(paste0("The unique-game file contains ", n(S[["ten_minute"]][["unique_games"]]), " 10|0 games. That count determines how informative this cohort is about direct reclassification. Grandmaster accounts may choose speed settings very differently from the wider user population. A small number of 10|0 observations would make this dataset weak evidence about platform-wide migration to rapid even though it can still audit comparator sensitivity."))
rows <- lapply(S[["ten_minute"]][["class_counts"]], function(x) list(x[["time_class"]], if (x[["post"]]) "post" else "pre", n(x[["n"]])))
if (length(rows)) table(list("Recorded class", "Period", "10|0 unique games"), rows, "llr", "Observed classification of 10-minute games in the frozen archives")
add("Removing 10|0 games from the pre-event blitz sample addresses the directly reclassified observations. It does not restore the counterfactual blitz pool: matchmaking opponents, player allocation, and the rating distribution of the remaining pool can respond to the same reform. Restricting to fixed settings is a useful audit and cannot establish a no-spillover control. Rapid is even less suitable as an untreated control because it was directly affected by the announcement.")
add("The honest causal conclusion is thus bounded. The panel can measure a bullet-relative rating shift in the observed accounts and assess its sensitivity. It cannot isolate the effect of the bullet offset from all simultaneous general-equilibrium changes in rating pools, nor identify a change in latent chess skill. A common administrative offset provides a strong mechanism for a level shift, but that mechanism is not evidence of an improvement in ability.")
section("First observed policy crossings and rollout timing")
add(paste0("There are ", n(T[["n"]]), " accounts with an observed bullet rating on both sides of the announcement for which the first post-event game crosses the date from the prior observed bullet game. The median observed change is ", f(T[["median_change"]]), " points; the mean is ", f(T[["mean_change"]]), ". The median first-observation delay is ", f(T[["median_days_after"]]), " days."))
fig("08_rollout", "First observed post-announcement bullet game minus the previous observed bullet rating. Scatter color encodes current score (0 = loss, 0.5 = draw, 1 = win); the offset line is 150. These changes include game updates and elapsed-time effects. Source: frozen cohort archives.")
add("The crossing statistic is not a clean measure of the administrative addition. It includes the result of the first post-event game, possibly multiple intervening rating adjustments, and delayed observation. A player can log in before playing, so first post-game observation is not the login time. The distribution is useful for consistency checks, and should not be converted into a staggered-adoption causal design without genuine treatment timestamps.")
section("Post-game information and outcome regressions")
sub("Retrospective association, not an operational forecast")
add("I fit a logistic regression to unique decisive games, with White win as the outcome, the post-game White-minus-Black rating gap in hundreds of points, pool indicators, post-period status, and a gap-by-post interaction. Draws are excluded, so the target is winning conditional on a decisive game, not expected score across all games. Standard errors are clustered by unordered opponent pair. Shared accounts across pairs and site-wide shocks remain sources of dependence.")
add("The descriptive model is\n\\begin{equation}\n\\operatorname{logit}\\Pr(W_g=1)=a+b\\,\\Delta R_g/100+\\eta_c+d\\,Post_g+q\\,(\\Delta R_g/100)Post_g.\n\\end{equation}\nBecause $\\Delta R_g$ is measured after game $g$, $b$ and $q$ cannot be read as ex ante predictive accuracy or as causal effects of ratings on winning.")
add(paste0("I fit the model using ", n(S[["outcome"]][["n"]]), " decisive games from ", n(S[["outcome"]][["pairs"]]), " observed opponent pairs. Its rating-gap coefficient is ", f(S[["outcome"]][["gap100"]], 3), " log-odds per 100 post-game points, while the post-period interaction is ", f(S[["outcome"]][["post_interaction"]], 3), " (p = ", f(S[["outcome"]][["post_interaction_p"]], 3), "). This is a parameter of a retrospective association."))
coefficients <- records(fread(file.path(OUT, "retrospective_outcome_logit.csv")))
table(list("Term", "Coefficient", "SE", "95\\% interval"), lapply(coefficients, function(x) list(esc(x[["term"]]), f(x[["coefficient"]], 3), f(x[["se"]], 3), paste0(paste0(f(x[["ci_low"]], 3), " to "), f(x[["ci_high"]], 3)))), "p{5.5cm}rrr", "Retrospective logistic regression; coefficients in log-odds, pair-clustered intervals")
fig("09_retrospective_association", "Binned White win fractions for decisive games against post-game rating differences, with at least 20 games per bin. The Elo-shaped line is an illustrative reference, not an ex ante calibration target for this conditional outcome. Source: unique cohort games.")
sub("An adjacent-rematch timing audit")
add("To quantify the timing problem without assuming symmetric rating exchanges, I locate a prior observed game between the same pair in the same speed class. I require the next game's start to be between 0 and 300 seconds after that game's end, and require that prior game to be the latest observed game for both accounts in that class. I then take both players' lagged ratings from the preceding game's post-game values, allowing color to switch.")
add("At least one sampled account's complete monthly archive is available, but an unsampled opponent could have an unobserved intervening game elsewhere. Five-minute adjacency is therefore a defensible proxy for prior information, not a guarantee of exact pre-game state. Refunds and other updates may also occur. No opponent rating is reconstructed by forcing a zero-sum points exchange, since uncertainty-aware rating updates need not be symmetric.")
rows <- lapply(S[["leakage_metrics"]], function(x) list(esc(x[["rating_source"]]), n(x[["n"]]), pct(x[["accuracy"]]), f(x[["brier"]], 4), f(x[["log_loss"]], 4)))
table(list("Rating source", "Games", "Accuracy", "Brier", "Log loss"), rows, "p{4.8cm}rrrr", "Same decisive rematches, fixed Elo-shaped probability mapping; lower losses are better")
fig("10_leakage_audit", "Left: post-game rating gap minus prior-rematch gap, grouped by the current result; boxplots omit outliers for display. Right: mean log loss using the same fixed probability curve on the same games. Source: adjacent decisive rematches, June--October 2020.")
add(paste0("Median gap updates are ", f(L[["median_update_white_win"]]), " points when White wins and ", f(L[["median_update_black_win"]]), " when Black wins. The equal-pair mean log-loss gain from post-game information is ", f(L[["equal_pair_logloss_gain"]], 4), ", with percentile interval [", f(L[["ci_low"]], 4), ", ", f(L[["ci_high"]], 4), "], resampling ", n(L[["pairs"]]), " opponent-pair clusters 10,000 times. Game-weighted mean losses in the table and equal-pair differences target different weights."))
add("This is a controlled timing comparison, not a learned prediction competition: the probability mapping is fixed and no model is tuned on future games. Its advantage is interpretability; its limitation is that an Elo-shaped curve is not a fitted Glicko forecast and the decisive-game restriction changes the target. The result shows how endpoint timing can alter apparent accuracy in this sample. It does not establish that every Chess.com prediction project is invalid, and it does not reproduce all conclusions of ChessIQ.")
section("Additional descriptive game analysis")
rows <- lapply(S[["unique_game_descriptive"]], function(x) list(x[["time_class"]], n(x[["n"]]), pct(x[["draw_rate"]]), f(x[["white_score"]], 3), f(x[["moves_median"]])))
table(list("Pool", "Unique games", "Draw share", "White mean score", "Median length"), rows, "lrrrr", "Unique-game descriptive statistics; length is the last full-move number in PGN")
fig("11_game_characteristics", "Draw shares and distributions of game length by speed class. Length is a PGN move-counter proxy rather than exact ply count; displayed boxplots omit outliers. Source: unique rated standard games, June--October 2020.")
add("Draw rates and game length supply useful context for the outcome analysis. They are not adjusted causal effects of longer thinking time: stronger players, different opponents, selected settings, and event formats may all vary across pools. Likewise, White's score in this cohort does not identify the causal advantage of color without evidence about color assignment and opponent selection.")
section("What can and cannot be concluded")
add("The strongest supported result is a reproducible measurement of rating behavior in a clearly defined historical cohort, together with explicit sensitivity to sample construction. The nominal 150-point policy is documented independently of the data, and an exactly common offset preserves relative rating gaps by algebra. These are compatible with a change in displayed rating scale without a demonstrated change in underlying ability.")
add("A weaker, conditional statement is that the fitted bullet-versus-blitz panel contrast resembles an announcement effect under untreated parallel trends and negligible comparator spillovers. The simultaneous reform, uncertain treatment timing, incomplete activity support, current-title sampling, and shared pool shocks mean those assumptions remain contestable. I therefore interpret my DiD estimate conditionally and do not label it an identified average treatment effect.")
add("Important limits are selection and survivorship; account-versus-person ambiguity; limited account clusters in tightly restricted settings; absent historical rating deviation and exact treatment receipt; rating refunds and possible retrospective archive changes; boundary-week exposure differences; outcome-dependent post-game measurement; rematch selection; and unobserved games by opponents outside sampled archives. Large game counts reduce some descriptive noise but do not remove these identification problems.")
sub("A stronger future causal design")
add("A credible extension would first obtain exact account-level rebase timestamps and pre-update ratings, ideally from platform logs, plus a cohort frame fixed before the reform. It would record whether each opponent had already been rebased at match start. Relative-exposure contrasts could then examine temporary mismatches during rollout, with pre-specified short windows and explicit tests for selection into login timing.")
add("Even that design would require handling interference: one player's rating is influenced by the opponents' states and by pool-wide matching. A randomized staged rollout, if a platform chose to conduct one, would offer stronger assignment evidence. A randomized experiment on rating display could study behavior while keeping the underlying matchmaking rating fixed; this is a proposal, not an experiment performed here.")
sub("Other interesting questions supported by extensions of these data")
add("Three specific follow-ups are promising. First, estimate how incomplete opponent histories affect reconstructed pre-game ratings by varying observed rematch gaps and validating against a fully observed two-account subpanel. Second, decompose category migration using a pre-defined cohort of 10|0 specialists, rather than this GM-oriented sample. Third, study whether post-game information creates different apparent prediction gains for low- versus high-uncertainty accounts when historical RD becomes available. These questions add measurement and identification value instead of repeating a generic rating correlation.")
section("Reproducibility and delivery")
add("I provide a complete reproducible project containing frozen compressed API responses, processed datasets, request and hash logs, collection and analysis code, all generated figures in PDF and PNG, numerical result tables, this report's LaTeX source, the compiled PDF, dependency pins, verification utilities, and a README. Rebuilding analysis from the frozen data requires no Chess.com credentials and no fresh data download. Re-fetching is optional and can change the contemporary sampling frame.")
add("From the repository root, restore the pinned R packages with \\texttt{Rscript scripts/setup.R}, run \\texttt{Rscript scripts/analyze.R}, then run \\texttt{Rscript scripts/verify.R} and \\texttt{Rscript scripts/build\\_report.R}. Compile from the report folder using \\texttt{tectonic report.tex}; an ordinary XeLaTeX installation can also compile the source twice. The delivered report is actually typeset from LaTeX, with vector figure inputs. The self-contained compiler used for delivery was Tectonic 0.17.0; portable Palatino, Helvetica, and Courier TeX fonts avoid dependence on installed desktop fonts.")
add("I release my original code and report text under an MIT license. Public platform data are attributed separately and are not relicensed by the code license. The source archives include public game handles and URLs for provenance; no private chats, emails, or authentication tokens were collected. The repository contains the source files, frozen data, estimates, figures and compiled report needed to inspect and reproduce my analysis.")
add("\\clearpage\\appendix")
section("Variable definitions and analytical checks")
table(list("Variable", "Definition / timing"), list(list("\\texttt{game\\_id}", "UUID, with public game URL as fallback"), list("\\texttt{rating}", "Focal account rating after the game, from JSON"), list("\\texttt{white\\_score}", "White result: 1, 0.5, 0; unique-game unit"), list("\\texttt{score}", "Focal account score, adjusted for color"), list("\\texttt{event\\_week}", "Floor of elapsed UTC time / seven days from 10 Sep"), list("\\texttt{post}", "Descriptive indicator for completion on/after 10 Sep"), list("\\texttt{treat}", "Bullet indicator times post, with week 0 omitted"), list("\\texttt{unit}", "Account-by-rating-pool panel identifier"), list("\\texttt{rating\\_change}", "Current minus prior observed focal rating in same pool"), list("\\texttt{lag\\_gap}", "White minus Black ratings from previous observed rematch"), list("\\texttt{pair}", "Unordered normalized account pair"), list("\\texttt{moves\\_proxy}", "Last numeric full-move counter in PGN")), "p{4.4cm}p{9cm}", "Core data dictionary; full columns are retained in processed CSV files")
add("Verification checks include uniqueness of game identifiers; one or two focal rows per unique sampled game; valid score and class values; temporal ordering for prior-rematch information; non-overlapping prior/current game times for the rematch audit; sufficient policy variation in the panel; full numerical output without invented rows; raw-response hash consistency; expected figure existence; and PDF text and page rendering checks. The verification file reports actual checks rather than substituting test outcomes for identification arguments.")
